      if (!frame) throw syntaxError("'else' outside a block", location);
      if (frame.hasElse) throw syntaxError("Duplicate 'else'", location);
      frame.hasElse = true;
      output = frame.node.type === "if" ? frame.node.falsy : frame.node.empty;
      continue;
    }

